using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Reflection;
using System.Windows.Forms;
namespace RcsMap {
 public static class ApplicationTests {
  static int checks;
  static void Check(bool ok,string message){if(!ok)throw new Exception("application: "+message);checks++;}
  static void Reject(Action action,string message){try{action();}catch{checks++;return;}throw new Exception("application should reject: "+message);}
  public static MapDocument Fixture(){var d=MapDocument.Demo();d.Version=7;d.Application=new ApplicationSettings{Enabled=true,AutoStart=true,StartAtP0=true};return d;}
  public static void WriteFixture(string path){File.WriteAllText(path,Fixture().Json(),new System.Text.UTF8Encoding(false));}
  static void Change(MapDocument d,Action<ApplicationSettings> edit){var c=d.Clone();edit(c.Application);c.StructuralCheck();}
  public static void Run(string folder){
   Directory.CreateDirectory(folder);checks=0;var old=MapDocument.Demo();string oldJson=old.Json();Check(old.Application==null&&!oldJson.Contains("Application"),"old maps remain unconfigured");Check(old.Clone().Version==3&&old.Clone().Application==null,"old map clone cannot enable motion");
   var imported=MapDocument.Demo();imported.ImportChassis("#define RCS_LAYOUT 1\n#define RCS_WHEEL_DIAMETER_MM 100\n#define RCS_WHEELBASE_MM 300\n#define RCS_TRACK_MM 300\n#define RCS_OMNI_RADIUS_MM 200\n#define RCS_OMNI_THETA0_DEG 0\n#define RCS_GEAR_RATIO 19.2032\n#define RCS_MAX_MOTOR_RPM 3000\n#define RCS_CAN_BUS 2\n#define RCS_MOTOR_ID_0 3\n#define RCS_MOTOR_ID_1 1\n#define RCS_MOTOR_ID_2 2\n#define RCS_MOTOR_ID_3 4\n");Check(imported.Version==7&&!imported.Application.Enabled,"explicit import creates disabled v7 configuration");Check(imported.Application.CanBus==2&&imported.Application.MotorId0==3&&imported.Application.MotorId1==1,"import maps actual bus and motor IDs");
   var d=Fixture();Check(d.Validate().Count==0,"valid explicit application");Check(d.Clone().Json()==d.Json(),"v7 preserves whole state machine");Check(d.Application.States.Select(s=>s.Id).Distinct().Count()==2,"stable state IDs");
   Reject(()=>{var c=d.Clone();c.Version=6;c.StructuralCheck();},"new data with old schema");
   Reject(()=>Change(d,a=>a.States[0].Initial=false),"no initial");Reject(()=>Change(d,a=>a.States[1].Initial=true),"two initials");Reject(()=>Change(d,a=>a.States[1].Id=a.States[0].Id),"duplicate state ID");
   Reject(()=>Change(d,a=>a.States[0].Transitions[0].TargetId="missing"),"dangling transition");Reject(()=>Change(d,a=>a.States[0].Transitions[0].Condition=""),"empty transition");Reject(()=>Change(d,a=>a.States[0].Timeout=0),"nonpositive timeout");Reject(()=>Change(d,a=>{a.States[0].Kind=2;a.States[0].WaitSeconds=0;}),"nonpositive wait");Reject(()=>Change(d,a=>a.StartAtP0=false),"autostart route needs physical pose confirmation");Reject(()=>Change(d,a=>a.MotorId1=a.MotorId0),"duplicate motor mapping");Reject(()=>Change(d,a=>a.CanHandleName="hcan;evil"),"invalid C handle");
   Reject(()=>Change(d,a=>a.States[0].Tick=new String('x',16385)),"oversized callback");Reject(()=>Change(d,a=>a.States[0].Enter="/* USER CODE BEGIN X */"),"reserved marker");
   string rev=TemplateGenerator.RouteRevision(d);d.Application.BootDelayMs++;Check(rev!=TemplateGenerator.RouteRevision(d),"revision includes application");d.Application.BootDelayMs--;
   var terrain=TerrainGeometry.Demo();terrain.Version=7;terrain.Application=new ApplicationSettings();DraftRules.Check(terrain);Check(terrain.Clone().Version==7,"v7 coexists with terrain");DraftRules.Terrain(terrain);Check(terrain.Version==7,"terrain edit never downgrades");
   var hardware=CorrectionTests.Fixture();hardware.Version=7;hardware.Application=new ApplicationSettings();Check(hardware.Clone().Version==7,"v7 coexists with observers");
   var code=Exporter.Generate(d);Check(code.Count==19,"flat application19");Check(code.ContainsKey("app.c")&&code.ContainsKey("machism.c"),"standard modules emitted");Check(code["rcs_app_config.h"].Contains("RCS_APP_AUTOSTART"),"config rendered");
   var legacy1=Exporter.Generate(old);var legacy2=Exporter.Generate(old);Check(legacy1.All(p=>legacy2[p.Key]==p.Value),"unconfigured generation deterministic");
   d.Application.States[0].Enter="/* stable state body */";var before=Exporter.Generate(d)["machism.c"];var custom=before.Replace("/* stable state body */","/* preserved state custom */");d.Application.States[0].Name="重命名不改变ID";var after=Exporter.Generate(d)["machism.c"];Check(UserRegions.Merge(custom,after).Contains("preserved state custom"),"stable state callback merge");
   var machine=Fixture();machine.Application.Includes="extern int machine_test_enter, machine_test_tick, machine_test_exit, machine_test_cancel;";var route=machine.Application.States[0];route.Enter="++machine_test_enter;";route.Tick="++machine_test_tick;";route.Exit="++machine_test_exit;";route.Cancel="++machine_test_cancel;";string output=Path.Combine(folder,"runtime");Directory.CreateDirectory(output);foreach(var file in Exporter.Generate(machine))File.WriteAllText(Path.Combine(output,file.Key),file.Value,new System.Text.UTF8Encoding(false));
   var priority=machine.Clone();var ignored=new MachineState{Name="低优先级完成",Kind=3};priority.Application.States.Add(ignored);priority.Application.States[0].Transitions.Add(new MachineTransition{TargetId=ignored.Id,Condition="complete"});var priorityDir=Path.Combine(folder,"priority");Directory.CreateDirectory(priorityDir);foreach(var file in Exporter.Generate(priority))File.WriteAllText(Path.Combine(priorityDir,file.Key),file.Value,new System.Text.UTF8Encoding(false));
   var wait=machine.Clone();wait.Application.States[0].Kind=2;wait.Application.States[0].WaitSeconds=.03;wait.Application.States[0].Timeout=.2;var waitDir=Path.Combine(folder,"wait");Directory.CreateDirectory(waitDir);foreach(var file in Exporter.Generate(wait))File.WriteAllText(Path.Combine(waitDir,file.Key),file.Value,new System.Text.UTF8Encoding(false));
   var none=machine.Clone();none.Application.States.Clear();none.Application.States.Add(new MachineState{Kind=3,Initial=true,Name="仅完成"});var noneDir=Path.Combine(folder,"none");Directory.CreateDirectory(noneDir);foreach(var file in Exporter.Generate(none))File.WriteAllText(Path.Combine(noneDir,file.Key),file.Value,new System.Text.UTF8Encoding(false));
   var lifecycle=machine.Clone();lifecycle.Application.Includes="int machine_callback(int phase);";var first=lifecycle.Application.States[0];first.Kind=0;first.Enter="(void)machine_callback(1);";first.Tick="(void)machine_callback(2);";first.Complete="machine_callback(3)";first.Exit="(void)machine_callback(5);";first.Cancel="(void)machine_callback(6);";first.Transitions[0].Condition="machine_callback(4) && complete";lifecycle.Application.States[1].Enter="(void)machine_callback(7);";lifecycle.Application.States[1].Tick="/* terminal tick */";lifecycle.Application.States[1].Exit="(void)machine_callback(8);";lifecycle.Application.States[1].Cancel="(void)machine_callback(9);";var lifeDir=Path.Combine(folder,"lifecycle");Directory.CreateDirectory(lifeDir);foreach(var file in Exporter.Generate(lifecycle))File.WriteAllText(Path.Combine(lifeDir,file.Key),file.Value,new System.Text.UTF8Encoding(false));
   var candidate=d.Clone();string untouched=d.Json();using(var dialog=new ApplicationDialog(candidate)){candidate.Application.BootDelayMs+=10;dialog.DialogResult=DialogResult.Cancel;}Check(d.Json()==untouched,"dialog cancel source unchanged");
   using(var editor=new Editor()){var field=typeof(Editor).GetField("doc",BindingFlags.Instance|BindingFlags.NonPublic);field.SetValue(editor,d.Clone());editor.BeginChange();var modified=(MapDocument)field.GetValue(editor);modified.Application.BootDelayMs+=10;editor.EndChange();typeof(Editor).GetMethod("Undo",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(editor,null);Check(((MapDocument)field.GetValue(editor)).Json()==d.Json(),"global undo includes app");typeof(Editor).GetMethod("Redo",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(editor,null);Check(((MapDocument)field.GetValue(editor)).Application.BootDelayMs==d.Application.BootDelayMs+10,"redo includes app");}
   File.WriteAllText(Path.Combine(folder,"application.rcsmap.json"),d.Json());File.WriteAllText(Path.Combine(folder,"application-selftest.txt"),"PASS "+checks+" application/model/UI/generation checks\n");Console.WriteLine("PASS "+checks+" application/model/UI/generation checks");
  }
  public static void Render(string path){using(var dialog=new ApplicationDialog(Fixture())){dialog.ShowInTaskbar=false;dialog.Opacity=0;dialog.Show();dialog.Refresh();Application.DoEvents();using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}dialog.Close();}}
 }
}
